export const AttachmentAction = defineComponent({
	name: 'AttachmentAction',
	props: {
		variant: { type: String as PropType<ButtonVariant>, default: 'ghost' },
		size: { type: String as PropType<ButtonSize>, default: 'icon-xs' },
	},
	setup(props, { slots, attrs }) {
		return () => {
			const userClass = attrs.class;
			const restAttrs = { ...attrs };
			delete restAttrs.class;

			return h(
				Button,
				{
					...restAttrs,
					'data-slot': 'attachment-action',
					variant: props.variant,
					size: props.size,
					class: [styles[attachmentStyleKeys.action], userClass],
				},
				slots.default?.(),
			);
		};
	},
});

export const AttachmentTrigger = defineComponent({
	name: 'AttachmentTrigger',
	inheritAttrs: false,
	props: {
		asChild: { type: Boolean, default: false },
		type: { type: String as PropType<'button' | 'submit' | 'reset'>, default: 'button' },
	},
	setup(props, { slots, attrs }) {
		return () => {
			const userClass = attrs.class;
			const restAttrs = { ...attrs };
			delete restAttrs.class;

			const triggerProps = {
				...restAttrs,
				'data-slot': 'attachment-trigger',
				type: props.asChild ? undefined : props.type,
				class: [styles[attachmentStyleKeys.trigger], userClass],
			};

			if (props.asChild) {
				const child = slots.default?.()[0];
				if (child) {
					return cloneVNode(child, mergeProps(child.props ?? {}, triggerProps));
				}
				return null;
			}

			return h('button', triggerProps, slots.default?.());
		};
	},
});

export const AttachmentCard = defineComponent({
	name: 'AttachmentCard',
	props: {
		name: { type: String, default: undefined },
		size: { type: Number, default: undefined },
		file: { type: File, default: undefined },
		state: { type: String as PropType<AttachmentState>, default: 'done' },
		orientation: { type: String as PropType<AttachmentOrientation>, default: 'horizontal' },
		downloading: { type: Boolean, default: false },
		action: { type: [Object, Function], default: undefined },
	},
	emits: ['remove', 'download', 'preview', 'click'],
	setup(props, { attrs, emit }) {
		return () => {
			const kind = getAttachmentFileKind(props.name, props.file?.type);
			const actionable = isAttachmentActionable(props.state);
			const displayName = props.name ? truncateAttachmentName(props.name) : '';
			const description = props.size !== undefined ? formatAttachmentSize(props.size) : props.state;

			const userClass = attrs.class;
			const restAttrs = { ...attrs };
			delete restAttrs.class;

			const actions: unknown[] = [];
			if (hasListener(attrs, 'download')) {
				actions.push(
					h(AttachmentAction, { 'aria-label': '下载', disabled: !actionable || props.downloading, onClick: (event: MouseEvent) => emit('download', event) }, () =>
						downloadIcon(),
					),
				);
			}
			if (props.action != null) {
				actions.push(props.action);
			} else if (hasListener(attrs, 'remove')) {
				actions.push(h(AttachmentAction, { 'aria-label': '删除', disabled: !actionable, onClick: (event: MouseEvent) => emit('remove', event) }, () => trashIcon()));
			}

			const children: unknown[] = [
				h(AttachmentMedia, { variant: 'icon' }, () => h(AttachmentFileIcon, { kind })),
				h(AttachmentContent, {}, () => [
					displayName ? h(AttachmentTitle, {}, () => displayName) : null,
					description ? h(AttachmentDescription, {}, () => description) : null,
				]),
			];
			if (actions.length > 0) {
				children.push(h(AttachmentActions, {}, () => actions));
			}

			return h(
				Attachment,
				{
					...restAttrs,
					state: props.state,
					orientation: props.orientation,
					class: [styles[attachmentStyleKeys.card], userClass],
					onClick: (event: MouseEvent) => emit('click', event),
				},
				() => children,
			);
		};
	},
});

function hasListener(attrs: Record<string, unknown>, name: string): boolean {
	return typeof attrs[`on${name.charAt(0).toUpperCase()}${name.slice(1)}`] === 'function';
}

export default Attachment;

@use '../../../styles/variables/colors' as *;

// 附件根容器
.attachment {
	position: relative;
	display: flex;
	width: fit-content;
	max-width: 100%;
	min-width: 0;
	flex-shrink: 0;
	flex-wrap: wrap;
	border: 1px solid var(--tile-attachment-border, $border);
	border-radius: var(--tile-attachment-radius, $radius);
	background-color: var(--tile-attachment-background, $card);
	color: $card-foreground;
	transition:
		background-color $transition-fast,
		border-color $transition-fast;

	&:focus-within {
		outline: none;
		box-shadow: var(--tile-attachment-focus-shadow, 0 0 0 1px color-mix(in srgb, $ring 50%, transparent));
	}

	// 尺寸
	&[data-size='default'] {
		gap: $spacing-2;
		padding-inline: $spacing-2_5;

		.content {
			padding: $spacing-2 0;
		}

		.media {
			padding: $spacing-2 0;
		}
	}

	&[data-size='sm'] {
		gap: $spacing-2_5;
		padding-inline: $spacing-2;

		.content {
			padding: $spacing-1_5 0;
		}

		.media {
			padding: $spacing-1_5 0;
		}
	}

	&[data-size='xs'] {
		gap: $spacing-1_5;
		padding-inline: $spacing-1_5;
		border-radius: $radius-md;

		.content {
			padding: $spacing-1 0;
		}

		.media {
			padding: $spacing-1 0;
		}
	}

	// 排版方向
	&[data-orientation='horizontal'] {
		min-width: 10rem;
		align-items: center;
	}

	&[data-orientation='vertical'] {
		width: 6rem;
		flex-direction: column;

		.content {
			width: 100%;
		}
	}

	// 状态
	&[data-state='idle'] {
		border-style: dashed;
	}

	&[data-state='error'] {
		border-color: var(--tile-attachment-error-border, color-mix(in srgb, $destructive 30%, transparent));
	}

	&:has(> a, > button):hover {
		background-color: var(--tile-attachment-hover-background, color-mix(in srgb, $muted 50%, transparent));
	}
}

// 附件卡片（AttachmentCard 组合根）
.card {
	position: relative;
	display: flex;
	width: 100%;
	min-width: 0;
	align-items: center;
	gap: $spacing-2;
	border-radius: var(--tile-attachment-radius, $radius);
	background-color: var(--tile-attachment-background, $card);
	color: $card-foreground;
	transition:
		background-color $transition-fast,
		border-color $transition-fast;

	&[data-orientation='vertical'] {
		flex-direction: column;
		align-items: flex-start;
	}

	&[data-state='idle'] {
		border: 1px dashed var(--tile-attachment-border, $border);
	}

	&[data-state='error'] {
		border-color: var(--tile-attachment-error-border, color-mix(in srgb, $destructive 30%, transparent));
	}
}

// 媒体区
.media {
	position: relative;
	display: flex;
	width: 2.5rem;
	height: 2.5rem;
	flex-shrink: 0;
	align-items: center;
	justify-content: center;
	overflow: hidden;
	border-radius: $radius;
	background-color: var(--tile-attachment-media-background, $muted);
	color: $foreground;

	svg {
		pointer-events: none;
		flex-shrink: 0;
		width: $spacing-4;
		height: $spacing-4;
	}

	// 变体
	&.variantIcon {
		[data-size='xs'] & {
			width: 1.75rem;
			height: 1.75rem;
			border-radius: $radius-md;

			svg {
				width: 0.875rem;
				height: 0.875rem;
			}
		}

		[data-orientation='vertical'] & {
			width: 100%;

			svg {
				width: $spacing-6;
				height: $spacing-6;
			}
		}
	}

	&.variantImage {
		opacity: 0.6;

		img {
			width: 100%;
			height: 100%;
			aspect-ratio: 1 / 1;
			object-fit: cover;
		}

		[data-state='done'] &,
		[data-state='idle'] & {
			opacity: 1;
		}
	}

	// 状态
	[data-state='error'] & {
		background-color: var(--tile-attachment-error-background, color-mix(in srgb, $destructive 10%, transparent));
		color: var(--tile-attachment-error-color, $destructive);
	}
}

// 内容区
.content {
	display: flex;
	min-width: 0;
	flex: 1;
	flex-direction: column;
	line-height: $leading-tight;
}

// 标题
.title {
	display: block;
	max-width: 100%;
	min-width: 0;
	overflow: hidden;
	font-weight: $font-medium;
	text-overflow: ellipsis;
	white-space: nowrap;

	[data-state='processing'] &,
	[data-state='uploading'] & {
		color: $muted-foreground;
	}
}

// 描述
.description {
	display: block;
	margin-top: 0.125rem;
	min-width: 0;
	overflow: hidden;
	font-size: $text-xs;
	color: $muted-foreground;
	text-overflow: ellipsis;
	white-space: nowrap;

	[data-state='error'] & {
		color: var(--tile-attachment-error-color, color-mix(in srgb, $destructive 80%, transparent));
	}
}

// 操作区
.actions {
	position: relative;
	z-index: 20;
	display: flex;
	flex-shrink: 0;
	align-items: center;
	gap: $spacing-1;

	[data-orientation='vertical'] & {
		position: absolute;
		top: $spacing-3;
		right: $spacing-3;
	}
}

// 单个操作按钮
.action {
	display: inline-flex;
	flex-shrink: 0;
	align-items: center;
	justify-content: center;
	border: none;
	border-radius: $radius;
	background-color: transparent;
	color: $muted-foreground;
	cursor: pointer;
	transition:
		background-color $transition-fast,
		color $transition-fast;

	&:hover {
		background-color: $muted;
		color: $foreground;
	}

	&:focus-visible {
		outline: none;
		box-shadow: var(--tile-attachment-focus-shadow, 0 0 0 1px $ring);
	}

	&:disabled {
		pointer-events: none;
		opacity: 0.5;
	}

	svg {
		width: $spacing-4;
		height: $spacing-4;
	}
}

// 触发层（覆盖整个附件，点击跳转/选择）
.trigger {
	position: absolute;
	inset: 0;
	z-index: 10;
	outline: none;
	cursor: pointer;
}

// 附件组（横向滚动容器）
.group {
	display: flex;
	min-width: 0;
	gap: $spacing-3;
	overflow-x: auto;
	overscroll-behavior-x: contain;
	padding-block: $spacing-1;

	> [data-slot='attachment'],
	> .attachment {
		flex: none;
	}
}
